export const getGraphSources = id => checked(request.get(`${base}/${encodeURIComponent(id)}/sources`, options))
export const saveGraphDraft = (id, data) => checked(request.patch(`${base}/${encodeURIComponent(id)}/draft`, data, options))
export const publishGraph = (id, revision) => checked(request.post(`${base}/${encodeURIComponent(id)}/publish`, { revision }, options))
export const getGraphJob = (id, jobId) => checked(request.get(`${base}/${encodeURIComponent(id)}/jobs/${encodeURIComponent(jobId)}`, options))
